theorem j_rec {k ℓ : ℕ}
    (h : ¬ (ℓ ≤ k * (k - 1) * (k - 2) ∨ k * (k - 1) * (k - 2) - k = 0)) :
    j k ℓ = j k (ℓ - ell0 k) + j k (ell0 k) + 3

theorem block_is_full_cycle (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {B r : ℕ}
    (hdvd : k ∣ B) (hr : r < k) (hB : B + r < p.numVerts) :
    p.vert (B + r) = sigma^[r] (p.vert B)

theorem exitless_step (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {i : ℕ}
    (hi : i + 1 < p.numVerts) :
    p.vert (i + 1) = sigma (p.vert i) ∨ p.pos (sigma (p.vert i)) ≤ i

theorem no_reentry (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {B B' : ℕ}
    (hdvd : k ∣ B) (hBk : B + k ≤ B') (hB'n : B' < p.numVerts) :
    rotClass (p.vert B).1 ≠ rotClass (p.vert B').1

theorem vert_succ (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {i : ℕ}
    (hi : i + 1 < p.numVerts) (hnd : ¬ k ∣ (i + 1)) :
    p.vert (i + 1) = sigma (p.vert i)

theorem vert_succ_ne (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {i : ℕ}
    (hi : i + 1 < p.numVerts) (hd : k ∣ (i + 1)) :
    p.vert (i + 1) ≠ sigma (p.vert i)

theorem card_Vset_le {A : Vtx k} (hk : 2 ≤ k) {α : ℕ} {K : RotClass}
    (hα : α = (A : List ℕ).getLastD 0) (hK : K = rotClass (A : List ℕ).dropLast) :
    (Vset k α K).card ≤ k * (k - 1)

theorem insert_pos_inj {w : List ℕ} {α : ℕ} (hα : α ∉ w) {j j' : ℕ}
    (hj : j ≤ w.length) (hj' : j' ≤ w.length)
    (heq : w.take j ++ α :: w.drop j = w.take j' ++ α :: w.drop j') : j = j'

theorem fresh_run_le {blk : ℕ → List ℕ} {vis : RotClass → Prop} {p F : ℕ}
    (hp : vis (rotClass (blk p)))
    (hfresh : ∀ j, j < F → ¬ vis (rotClass (blk j))) : F ≤ p

theorem boundary_ge_two (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {i : ℕ}
    (hin : i + 1 < p.numVerts) (hd : k ∣ (i + 1)) :
    2 ≤ ew k (p.vert i) (p.vert (i + 1))

theorem heavy_is_boundary (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {i : ℕ}
    (hin : i + 1 < p.numVerts) (hh : 2 ≤ ew k (p.vert i) (p.vert (i + 1))) :
    k ∣ (i + 1)

theorem rho_boundary_prev (hk : 1 ≤ k) {p : HPath k} (hp : p.Exitless) {t : ℕ}
    (ht : 1 ≤ t) (hN : k * t ≤ p.numVerts) :
    (rho (p.vert (k * t - 1) : List ℕ)) = (p.vert (k * (t - 1)) : List ℕ)

theorem b1 {k : ℕ}
    (h_wP : ∀ (P : HPath k), P.IsHamiltonian →
      P.wtP ≥ (numComps (F P) - 1) + MinThrough (F P) + wEdges (F P)) :
    L k ≥ sInf {m | ∃ X, X ∈ Xk k ∧ m = (numComps X - 1) + MinThrough X + wEdges X}

theorem clm_rule1 {P : HPath k} (_hP : P.IsHamiltonian) {v : Vtx k}
    (hv : v ∈ Cm1 P) (hne : outV (F P) v ≠ ∅) :
    outV (F P) v = outV P.edges v

theorem clm_rule2 {P : HPath k} (_hP : P.IsHamiltonian) {v : Vtx k}
    (hv : v ∉ Cm1 P) :
    outV (F P) v = {(v, sigma v)}

theorem clm_rule2_5 {P : HPath k} (_hP : P.IsHamiltonian) {v : Vtx k}
    (hv : v ∉ C0 P) :
    intoV (F P) v = {(sigmaInv v, v)}

theorem clm_rule2_75 {P : HPath k} (_hP : P.IsHamiltonian) {u : Vtx k}
    (hu : u ∉ Cm1 P) :
    (u, sigma u) ∈ F P

theorem clm_rule3 {P : HPath k} (hP : P.IsHamiltonian) {u : Vtx k}
    (hu : u ∈ Cm1 P) (hne : outV (F P) u ≠ ∅) :
    ∃ v, v ∈ C0 P ∧ outV (F P) u = {(u, v)}

theorem c0_unique {P : HPath k} (hP : P.IsHamiltonian) {a b : Vtx k}
    (ha : firstInCycle P a) (hb : firstInCycle P b) (hr : rotClass a.1 = rotClass b.1) :
    a = b

theorem chain_prev_mem {f : Vtx k → Option (Vtx k)} {L : List (Vtx k)}
    (hL : L.IsChain (fun a b => f a = some b)) {x : Vtx k}
    (hx : x ∈ L) (hxh : L.head? ≠ some x) : ∃ b, (b, x) ∈ L.zip L.tail

theorem chain_step_mem {f : Vtx k → Option (Vtx k)} {L : List (Vtx k)}
    (hL : L.IsChain (fun a b => f a = some b))
    (hlast : ∀ z, L.getLast? = some z → f z = none) {x y : Vtx k}
    (hx : x ∈ L) (hxy : f x = some y) : (x, y) ∈ L.zip L.tail

theorem iterOpt_mem_closed (f : Vtx k → Option (Vtx k)) {C : Finset (Vtx k)}
    (hstep : ∀ a b, f a = some b → a ∈ C → b ∈ C) :
    ∀ (n : ℕ) (v : Vtx k), v ∈ C → ∀ x ∈ iterOpt f n v, x ∈ C

theorem idxOf_flatten_lt {α : Type*} [BEq α] [LawfulBEq α] {blocks : List (List α)}
    (hnd : blocks.flatten.Nodup) {D : List α} (hD : D ∈ blocks) {a b : α}
    (ha : a ∈ D) (hb : b ∈ D) (hab : D.idxOf a < D.idxOf b) :
    blocks.flatten.idxOf a < blocks.flatten.idxOf b

theorem idxOf_flatten_succ {α : Type*} [BEq α] [LawfulBEq α] {blocks : List (List α)}
    (hnd : blocks.flatten.Nodup) {D : List α} (hD : D ∈ blocks) {a b : α}
    (ha : a ∈ D) (hb : b ∈ D) (hab : D.idxOf b = D.idxOf a + 1) :
    blocks.flatten.idxOf b = blocks.flatten.idxOf a + 1

theorem mem_tails {ps : List (HPath k)} {p : HPath k} (hp : p ∈ ps) {v : Vtx k}
    (hv : v ∈ p.verts.drop 1) :
    v ∈ (ps.reverse.map (fun p => p.verts.drop 1)).flatten

theorem first_edge_mem_addedEdges {ps : List (HPath k)} {p : HPath k}
    (hpdl : p ∈ ps.dropLast) :
    (p.first, sigma p.first) ∈ addedEdges (headSet ps)

theorem mem_doubles_of (P : HPath k) (S : Finset (Vtx k)) {a b v : Vtx k}
    (hab : (a, b) ∈ P.edges) (haS : a ∉ S) (hvS : v ∈ S) (hσ : sigma v = b) :
    b ∈ doubles P S
